import {
  DomainError,
  type Project,
  type Task,
  type TaskStatus,
  type User,
  taskStatuses,
} from "../domain/entities";

export interface CreateTaskInput {
  title: string;
  description: string;
  dueDate?: string;
  status?: TaskStatus;
  assigneeId?: string;
}

export interface TaskFilters {
  status?: TaskStatus;
  assigneeId?: string;
}

export class TaskManagementService {
  private readonly users = new Map<string, User>();
  private readonly projects = new Map<string, Project>();
  private readonly tasks = new Map<string, Task>();
  private nextUserId = 1;
  private nextProjectId = 1;
  private nextTaskId = 1;

  public createUser(name: string): User {
    this.requireText(name, "name");
    const user: User = { id: String(this.nextUserId++), name: name.trim() };
    this.users.set(user.id, user);
    return user;
  }

  public createProject(name: string): Project {
    this.requireText(name, "name");
    const project: Project = { id: String(this.nextProjectId++), name: name.trim() };
    this.projects.set(project.id, project);
    return project;
  }

  public createTask(projectId: string, input: CreateTaskInput): Task {
    this.getProject(projectId);
    this.requireText(input.title, "title");
    this.requireText(input.description, "description");
    const status = input.status ?? "todo";
    this.requireStatus(status);
    this.validateDueDate(input.dueDate);
    if (input.assigneeId !== undefined) this.getUser(input.assigneeId);

    const task: Task = {
      id: String(this.nextTaskId++),
      projectId,
      title: input.title.trim(),
      description: input.description.trim(),
      ...(input.dueDate === undefined ? {} : { dueDate: input.dueDate }),
      status,
      ...(input.assigneeId === undefined ? {} : { assigneeId: input.assigneeId }),
    };
    this.tasks.set(task.id, task);
    return task;
  }

  public assignTask(taskId: string, assigneeId: string): Task {
    const task = this.getTask(taskId);
    this.getUser(assigneeId);
    task.assigneeId = assigneeId;
    return task;
  }

  public listProjectTasks(projectId: string, filters: TaskFilters = {}): Task[] {
    this.getProject(projectId);
    if (filters.status !== undefined) this.requireStatus(filters.status);
    if (filters.assigneeId !== undefined) this.getUser(filters.assigneeId);
    return [...this.tasks.values()].filter(
      (task) =>
        task.projectId === projectId &&
        (filters.status === undefined || task.status === filters.status) &&
        (filters.assigneeId === undefined || task.assigneeId === filters.assigneeId),
    );
  }

  public markTaskDone(taskId: string): Task {
    const task = this.getTask(taskId);
    if (task.status === "done") {
      throw new DomainError("Task is already done", 409);
    }
    task.status = "done";
    return task;
  }

  private getUser(id: string): User {
    const user = this.users.get(id);
    if (!user) throw new DomainError("User not found", 404);
    return user;
  }

  private getProject(id: string): Project {
    const project = this.projects.get(id);
    if (!project) throw new DomainError("Project not found", 404);
    return project;
  }

  private getTask(id: string): Task {
    const task = this.tasks.get(id);
    if (!task) throw new DomainError("Task not found", 404);
    return task;
  }

  private requireText(value: unknown, field: string): asserts value is string {
    if (typeof value !== "string" || value.trim() === "") {
      throw new DomainError(`${field} is required`);
    }
  }

  private requireStatus(status: string): asserts status is TaskStatus {
    if (!taskStatuses.includes(status as TaskStatus)) {
      throw new DomainError("status must be todo, in progress, or done");
    }
  }

  private validateDueDate(dueDate: string | undefined): void {
    if (dueDate !== undefined && (typeof dueDate !== "string" || Number.isNaN(Date.parse(dueDate)))) {
      throw new DomainError("dueDate must be a valid date");
    }
  }
}

